-- =============================================================================
-- Object:      dbo.usp_PushSubscription_SaveForEmployee
-- Type:        stored procedure
-- Purpose:     Saves the push subscription of an employee's browser (HU_09). An endpoint that already exists moves to
--              this employee with its new keys (the same phone, someone else signed in), so a phone never gets the
--              notices of the previous user.
-- Parameters:  @Id uniqueidentifier - id for a new row (sequential, generated by the API)
--              @EmployeeId uniqueidentifier - employee signed in on that browser
--              @Endpoint nvarchar(450), @P256dh nvarchar(200), @Auth nvarchar(200) - the browser's subscription
--              @Now datetime2 - current time (UTC)
-- Returns:     nothing
-- Author:      JulianH2
-- Jira:        ITACR-15
-- =============================================================================
CREATE OR ALTER PROCEDURE dbo.usp_PushSubscription_SaveForEmployee
    @Id uniqueidentifier,
    @EmployeeId uniqueidentifier,
    @Endpoint nvarchar(450),
    @P256dh nvarchar(200),
    @Auth nvarchar(200),
    @Now datetime2
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRANSACTION;

    UPDATE dbo.PushSubscriptions WITH (UPDLOCK, HOLDLOCK)
    SET EmployeeId = @EmployeeId, CustomerId = NULL, P256dh = @P256dh, Auth = @Auth, UpdatedAt = @Now
    WHERE Endpoint = @Endpoint;

    IF @@ROWCOUNT = 0
    BEGIN
        INSERT INTO dbo.PushSubscriptions (Id, EmployeeId, CustomerId, Endpoint, P256dh, Auth, CreatedAt, UpdatedAt)
        VALUES (@Id, @EmployeeId, NULL, @Endpoint, @P256dh, @Auth, @Now, @Now);
    END;

    COMMIT TRANSACTION;
END;
